request.query:
query List(
  $repo: String!, $rev: String!, $path: String!, $recursive: Boolean!,
  $first: Int!
) {
  repository(name: $repo) {
    name
    commit(rev: $rev) {
      oid
      node: path(path: $path) {
        __typename
        ... on GitBlob { path submodule { url commit } }
        ... on GitTree {
          path
          entries(first: $first, recursive: $recursive) {
            path isDirectory submodule { url commit }
          }
        }
      }
    }
  }
}
